def _scrypt(password: str, salt: str, n: int, r: int, p: int) -> bytes:
    return hashlib.scrypt(
        password.encode(), salt=salt.encode(), n=n, r=r, p=p,
        dklen=_SCRYPT_DKLEN, maxmem=_SCRYPT_MAXMEM,
