def hash_password(password: str, salt=None) -> str:
    salt = salt or os.urandom(16).hex()
    n, r, p = config.SCRYPT_N, config.SCRYPT_R, config.SCRYPT_P
    return f"scrypt${n}${r}${p}${salt}${_scrypt(password, salt, n, r, p).hex()}"


def verify_password(password: str, stored: str) -> bool:
    if not isinstance(stored, str):
        return False
    parts = stored.split("$")
    try:
        if parts[0] == "scrypt" and len(parts) == 6:
            _, n, r, p, salt, expected = parts
            digest = _scrypt(password, salt, int(n), int(r), int(p))
        elif parts[0] == "pbkdf2" and len(parts) == 4:
            _, iterations, salt, expected = parts
            digest = hashlib.pbkdf2_hmac("sha256", password.encode(), salt.encode(), int(iterations))
        else:
            return False
    except (ValueError, OverflowError, MemoryError):
        return False
    return hmac.compare_digest(digest.hex(), expected)


def needs_rehash(stored: str) -> bool:
    """True for hashes not made with the current scheme and cost parameters."""
    prefix = f"scrypt${config.SCRYPT_N}${config.SCRYPT_R}${config.SCRYPT_P}$"
    return not (isinstance(stored, str) and stored.startswith(prefix))
